    const resolutions = [...steps.querySelectorAll<HTMLSelectElement>("[data-conflict-resolution]")].map((select) => ({
      storeName: select.dataset.storeName as BackupConflictResolution["storeName"],
      id: select.dataset.recordId ?? "",
