 53	async function collectFiles(directory: string): Promise<string[]> {
 54	  const entries = await readdir(directory, { withFileTypes: true });
 55	  const files: string[] = [];
 56	  for (const entry of entries.sort((left, right) => left.name.localeCompare(right.name))) {
 57	    const path = join(directory, entry.name);
 58	    if (entry.isDirectory()) files.push(...(await collectFiles(path)));
 59	    else if (entry.isFile()) files.push(path);
 60	  }
 61	  return files;
 62	}
